 56327  static void js_array_buffer_update_typed_arrays(JSArrayBuffer *abuf)
 56328  {
 56329      uint32_t size_log2, size_elem;
 56330      struct list_head *el;
 56331      JSTypedArray *ta;
 56332      JSObject *p;
 56333      uint8_t *data;
 56334      int64_t len;
 56335
 56336      len = abuf->byte_length;
 56337      data = abuf->data;
 56338      // update lengths of all typed arrays backed by this array buffer
 56339      list_for_each(el, &abuf->array_list) {
 56340          ta = list_entry(el, JSTypedArray, link);
 56341          p = ta->obj;
 56342          if (p->class_id == JS_CLASS_DATAVIEW) {
 56343              if (ta->track_rab) {
 56344                  if (ta->offset < len)
 56345                      ta->length = len - ta->offset;
 56346                  else
 56347                      ta->length = 0;
 56348              }
 56349          } else {
 56350              p->u.array.count = 0;
 56351              p->u.array.u.ptr = NULL;
 56352              size_log2 = typed_array_size_log2(p->class_id);
 56353              size_elem = 1 << size_log2;
 56354              if (ta->track_rab) {
 56355                  if (len >= (int64_t)ta->offset + size_elem) {
 56356                      p->u.array.count = (len - ta->offset) >> size_log2;
 56357                      p->u.array.u.ptr = &data[ta->offset];
 56358                  }
 56359              } else {
 56360                  if (len >= (int64_t)ta->offset + ta->length) {
 56361                      p->u.array.count = ta->length >> size_log2;
 56362                      p->u.array.u.ptr = &data[ta->offset];
 56363                  }
 56364              }
 56365          }
 56366      }
 56367
 56368  }
