 56370  void JS_DetachArrayBuffer(JSContext *ctx, JSValueConst obj)
 56371  {
 56372      JSArrayBuffer *abuf = JS_GetOpaque(obj, JS_CLASS_ARRAY_BUFFER);
 56373
 56374      if (!abuf || abuf->detached)
 56375          return;
 56376      if (abuf->free_func)
